//! The host environment: what the embedding program provides to scripts (EMBEDDING §4).
//!
//! The checker's only host input is a [`HostEnv`], built by parsing interface (`.cbi`) text,
//! exactly as the prelude is built by parsing its source. A live `Vm` prints the text from its
//! registrations and parses it; `colibri check --interface engine.cbi` reads the same text from
//! a file. An interface file is Colibri syntax with an `@interface(..)` header line, then
//! body-less functions and `struct`/`enum`/`@host class` declarations:
//!
//! ```text
//! // Generated by colibri-runtime; do not edit.
//! @interface(format = 1, module = "host", hash = "9f2c41d07a3be518", caps = ["fs"])
//! struct Vec3 { x: f32, y: f32, z: f32 }
//! fn submit(a: f32, b: f32) -> Job
//! @requires(fs) fn read_save(path: str) -> Result[str]
//! ```
//!
//! The hash is FNV-1a 64 over everything after the header line (the canonical body); a file
//! whose hash does not match was edited by hand.

use std::collections::BTreeSet;

use colibri_syntax::ast::{self, ExprKind, ItemKind, PatKind, TopLevel};
use colibri_syntax::{FileId, SourceMap};

/// The source file id of every host interface; like the prelude's, its spans never point into
/// a user's file, and diagnostics never label them.
pub const HOST_FILE: FileId = FileId(u32::MAX - 1);

/// The interface format this checker reads.
pub const INTERFACE_FORMAT: u32 = 1;

/// The default module: its names are in scope everywhere without an import. Any other module
/// (`module = "physics"` in the header) is used with `import physics`.
pub const DEFAULT_MODULE: &str = "host";

/// The capabilities a host item can require (`@requires(cap)`), by their interface names.
pub const CAPABILITY_NAMES: &[&str] = &["fs", "os", "net", "ffi"];

/// FNV-1a, 64 bits. Stable across Rust versions and platforms (unlike `DefaultHasher`).
pub fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        hash ^= u64::from(b);
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    hash
}

/// The hash of a canonical interface body, as written in the header: sixteen hex digits.
pub fn body_hash(body: &str) -> String {
    format!("{:016x}", fnv1a64(body.as_bytes()))
}

/// The header line of an interface file.
pub fn header_line(module: &str, hash: &str, caps: &[String]) -> String {
    header_line_with(module, hash, caps, &[])
}

/// [`header_line`] for an interface that names types of other modules (`json.Value`): `uses`
/// are those modules, listed in the header when there are any, so a file that uses none reads
/// as it always did.
pub fn header_line_with(module: &str, hash: &str, caps: &[String], uses: &[String]) -> String {
    let list = |items: &[String]| {
        items
            .iter()
            .map(|c| format!("\"{c}\""))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let uses = if uses.is_empty() {
        String::new()
    } else {
        format!(", uses = [{}]", list(uses))
    };
    format!(
        "@interface(format = {INTERFACE_FORMAT}, module = \"{module}\", hash = \"{hash}\", caps = [{}]{uses})",
        list(caps)
    )
}

/// The parsed header of an interface file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InterfaceHeader {
    pub format: u32,
    pub module: String,
    pub hash: String,
    /// The capabilities that items of the interface require.
    pub caps: Vec<String>,
    /// The modules whose types the interface names, qualified (`json.Value` for `std.json`):
    /// their interfaces must be given too.
    pub uses: Vec<String>,
}

/// One parsed interface file.
#[derive(Clone, Debug)]
pub struct HostModule {
    pub header: InterfaceHeader,
    pub(crate) file: ast::File,
}

/// What the host provides: parsed interfaces and the capabilities the host granted.
#[derive(Clone, Debug, Default)]
pub struct HostEnv {
    pub(crate) modules: Vec<HostModule>,
    granted: BTreeSet<String>,
    all_granted: bool,
    /// The program is for a page (`os == "web"`): `task.run` and `task.tick` from `main` are
    /// refused with their own messages.
    web: bool,
}

impl HostEnv {
    /// A host that provides nothing and grants nothing.
    pub fn new() -> Self {
        Self::default()
    }

    /// Parses interface text into an environment. `Err` is a message with the position of
    /// the first problem.
    pub fn from_text(text: &str) -> Result<HostEnv, String> {
        let mut env = HostEnv::new();
        env.modules.push(parse_module(text)?);
        Ok(env)
    }

    /// Adds the interfaces of `other` (the capabilities it grants are added too).
    pub fn merge(&mut self, other: HostEnv) {
        self.modules.extend(other.modules);
        self.granted.extend(other.granted);
        self.all_granted |= other.all_granted;
        self.web |= other.web;
    }

    /// Says whether the program is for a web build, where a page has one thread and `main` is a
    /// coroutine (`BuildCfg::os` is `"web"`).
    pub fn set_web(&mut self, web: bool) {
        self.web = web;
    }

    /// Whether the program is for a web build.
    pub fn is_web(&self) -> bool {
        self.web
    }

    /// Grants a capability by its interface name (`fs`, `os`, `net`, `ffi`).
    pub fn grant(&mut self, cap: &str) {
        self.granted.insert(cap.to_string());
    }

    /// Grants every capability, including ones added later.
    pub fn grant_all(&mut self) {
        self.all_granted = true;
    }

    /// Whether the host granted the capability.
    pub fn is_granted(&self, cap: &str) -> bool {
        self.all_granted || self.granted.contains(cap)
    }

    /// The canonical text of each parsed interface, printed back from its declarations.
    pub fn canonical_texts(&self) -> Vec<String> {
        self.modules
            .iter()
            .map(HostModule::canonical_text)
            .collect()
    }

    /// The headers of the parsed interfaces, in order.
    pub fn headers(&self) -> impl Iterator<Item = &InterfaceHeader> {
        self.modules.iter().map(|m| &m.header)
    }

    /// Every top-level item of the default module's interfaces, in order.
    pub(crate) fn default_items(&self) -> impl Iterator<Item = &ast::Item> {
        self.module_items(DEFAULT_MODULE)
    }

    /// Every top-level item of the interfaces of module `name`, in order.
    pub(crate) fn module_items<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a ast::Item> {
        self.modules
            .iter()
            .filter(move |m| m.header.module == name)
            .flat_map(|m| m.file.items.iter())
            .filter_map(|top| match top {
                TopLevel::Item(item) => Some(item),
                TopLevel::Stmt(_) => None,
            })
    }

    /// The syntax trees of the interfaces of module `name`, in order (for editors: what
    /// `name.` offers; the default module `host` holds the functions that need no `import`).
    pub fn module_syntax<'a>(&'a self, name: &str) -> Vec<&'a ast::File> {
        self.module_files(name)
    }

    /// The syntax trees of the interfaces of module `name`, in order.
    pub(crate) fn module_files<'a>(&'a self, name: &str) -> Vec<&'a ast::File> {
        self.modules
            .iter()
            .filter(|m| m.header.module == name)
            .map(|m| &m.file)
            .collect()
    }

    /// The names of the modules the interfaces describe, each once, in order of appearance.
    pub fn module_names(&self) -> Vec<String> {
        let mut names: Vec<String> = Vec::new();
        for m in &self.modules {
            if !names.contains(&m.header.module) {
                names.push(m.header.module.clone());
            }
        }
        names
    }

    /// The modules whose types the interfaces of module `name` name (their `uses`).
    pub(crate) fn uses_of(&self, name: &str) -> Vec<String> {
        let mut uses: Vec<String> = Vec::new();
        for m in self.modules.iter().filter(|m| m.header.module == name) {
            for u in &m.header.uses {
                if !uses.contains(u) {
                    uses.push(u.clone());
                }
            }
        }
        uses
    }

    /// The pairs `(module, used module)` where an interface names the types of a module whose
    /// interface is not part of this environment: such a program cannot be checked until
    /// that interface is given too.
    pub fn missing_uses(&self) -> Vec<(String, String)> {
        let known = self.module_names();
        let mut missing = Vec::new();
        for m in &self.modules {
            for u in &m.header.uses {
                let pair = (m.header.module.clone(), u.clone());
                if !known.contains(u) && !missing.contains(&pair) {
                    missing.push(pair);
                }
            }
        }
        missing
    }

    /// The names of the modules other than the default one: what `import` can name.
    pub fn named_modules(&self) -> Vec<String> {
        self.module_names()
            .into_iter()
            .filter(|m| m != DEFAULT_MODULE)
            .collect()
    }
}

impl HostModule {
    /// The canonical text of the interface, printed from the parsed declarations. Printing
    /// what was parsed from canonical text gives the same text back, byte for byte.
    pub fn canonical_text(&self) -> String {
        let mut body = String::new();
        for top in &self.file.items {
            if let TopLevel::Item(item) = top {
                print_item(item, &mut body);
            }
        }
        let hash = body_hash(&body);
        format!(
            "{GENERATED}\n{}\n{body}",
            header_line_with(
                &self.header.module,
                &hash,
                &self.header.caps,
                &self.header.uses
            )
        )
    }
}

/// The comment that starts every generated interface file.
pub const GENERATED: &str = "// Generated by colibri-runtime; do not edit.";

/// `text` as the inside of a string literal of an interface file.
pub fn escape_text(text: &str) -> String {
    let mut out = String::new();
    for c in text.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out
}

fn print_attrs(item: &ast::Item, out: &mut String) {
    print_attr_list(&item.attrs, out);
}

fn print_attr_list(attrs: &[ast::Attr], out: &mut String) {
    for attr in attrs {
        out.push('@');
        out.push_str(&attr.name.name);
        if let [arg] = attr.args.as_slice() {
            match &arg.kind {
                ExprKind::Ident(id) => out.push_str(&format!("({})", id.name)),
                _ => {
                    if let Some(text) = crate::ffi::plain_string(arg) {
                        out.push_str(&format!("(\"{}\")", escape_text(&text)));
                    }
                }
            }
        }
        out.push(' ');
    }
}

fn print_item(item: &ast::Item, out: &mut String) {
    match &item.kind {
        ItemKind::Fn(decl) => {
            print_attrs(item, out);
            print_fn(decl, out);
            out.push('\n');
        }
        ItemKind::Struct(s) => {
            print_attrs(item, out);
            let fields: Vec<String> = s
                .fields
                .iter()
                .map(|f| {
                    let mut text = String::new();
                    print_attr_list(&f.attrs, &mut text);
                    format!("{text}{}: {}", f.name.name, print_type(&f.ty))
                })
                .collect();
            let word = match s.kind {
                ast::StructKind::Struct => "struct",
                ast::StructKind::Class => "class",
            };
            if fields.is_empty() {
                out.push_str(&format!("{word} {} {{}}\n", s.name.name));
            } else {
                out.push_str(&format!(
                    "{word} {} {{ {} }}\n",
                    s.name.name,
                    fields.join(", ")
                ));
            }
        }
        ItemKind::TypeAlias(t) => {
            print_attrs(item, out);
            out.push_str(&format!("type {} = {}\n", t.name.name, print_type(&t.ty)));
        }
        ItemKind::Enum(e) => {
            print_attrs(item, out);
            let variants: Vec<&str> = e.variants.iter().map(|v| v.name.name.as_str()).collect();
            out.push_str(&format!(
                "enum {} {{ {} }}\n",
                e.name.name,
                variants.join(", ")
            ));
        }
        ItemKind::Binding(b) => {
            if let (PatKind::Ident(name), Some(ty)) = (&b.pat.kind, &b.ty) {
                print_attrs(item, out);
                out.push_str(&format!(
                    "const {}: {} = {}\n",
                    name.name,
                    print_type(ty),
                    print_const(&b.init)
                ));
            }
        }
        ItemKind::Impl(decl) => {
            out.push_str(&format!("impl {} {{\n", print_type(&decl.target)));
            for member in &decl.items {
                if let ItemKind::Fn(f) = &member.kind {
                    out.push_str("    ");
                    print_attrs(member, out);
                    print_fn(f, out);
                    out.push('\n');
                }
            }
            out.push_str("}\n");
        }
        _ => {}
    }
}

/// The text of a constant's value: a number written as a literal.
fn print_const(init: &ast::Expr) -> String {
    match &init.kind {
        ExprKind::Int(v) => v.to_string(),
        ExprKind::Float(v) => float_literal(*v).unwrap_or_else(|| "0.0".to_string()),
        _ => "0".to_string(),
    }
}

fn print_fn(decl: &ast::FnDecl, out: &mut String) {
    let mut params: Vec<String> = Vec::new();
    if let Some(r) = decl.receiver {
        params.push(if r.mutable { "mut self" } else { "self" }.to_string());
    }
    for p in &decl.params {
        let ty = p.ty.as_ref().map_or("?".to_string(), print_type);
        params.push(format!("{}: {ty}", p.name.name));
    }
    let generics = if decl.generics.is_empty() {
        String::new()
    } else {
        let names: Vec<&str> = decl.generics.iter().map(|g| g.name.name.as_str()).collect();
        format!("[{}]", names.join(", "))
    };
    out.push_str(&format!(
        "fn {}{generics}({})",
        decl.name.name,
        params.join(", ")
    ));
    if let Some(ret) = &decl.ret {
        out.push_str(&format!(" -> {}", print_type(ret)));
    }
}

fn print_type(t: &ast::TypeExpr) -> String {
    use ast::TypeKind;
    match &t.kind {
        TypeKind::Named { path, args } => {
            let name: Vec<&str> = path.iter().map(|i| i.name.as_str()).collect();
            if args.is_empty() {
                name.join(".")
            } else {
                let args: Vec<String> = args.iter().map(print_type).collect();
                format!("{}[{}]", name.join("."), args.join(", "))
            }
        }
        TypeKind::Optional(inner) => format!("Option[{}]", print_type(inner)),
        TypeKind::Weak(inner) => format!("weak {}", print_type(inner)),
        TypeKind::Tuple(items) => {
            let items: Vec<String> = items.iter().map(print_type).collect();
            format!("({})", items.join(", "))
        }
        TypeKind::Fn { params, ret } => {
            let params: Vec<String> = params.iter().map(print_type).collect();
            match ret {
                Some(r) => format!("fn({}) -> {}", params.join(", "), print_type(r)),
                None => format!("fn({})", params.join(", ")),
            }
        }
        TypeKind::Never => "!".to_string(),
        TypeKind::Array { .. } | TypeKind::Error => "?".to_string(),
    }
}

/// Splits interface text into its header line and the rest, and parses both.
fn parse_module(text: &str) -> Result<HostModule, String> {
    let mut sources = SourceMap::new();
    let file = sources.add_file("interface", text);
    let at = |offset: usize, message: &str| {
        let (line, col) = sources.line_col(file, offset as u32);
        format!("{line}:{col}: {message}")
    };
    // The header is the first line that is neither blank nor a `//` comment.
    let mut offset = 0;
    let mut header = None;
    for line in text.split_inclusive('\n') {
        let trimmed = line.trim();
        if !(trimmed.is_empty() || trimmed.starts_with("//")) {
            header = Some((offset, line));
            break;
        }
        offset += line.len();
    }
    let Some((start, line)) = header else {
        return Err(at(
            0,
            "an interface file starts with an `@interface(..)` line",
        ));
    };
    let content = line.trim_end_matches(['\n', '\r']);
    let Some(args) = content
        .trim()
        .strip_prefix("@interface(")
        .and_then(|rest| rest.strip_suffix(')'))
    else {
        return Err(at(start, "expected an `@interface(..)` header line"));
    };
    let header = parse_header(args).map_err(|m| at(start, &m))?;
    if header.format != INTERFACE_FORMAT {
        return Err(at(
            start,
            &format!(
                "this is interface format {}, but this tool reads format {INTERFACE_FORMAT}",
                header.format
            ),
        ));
    }
    if !is_module_name(&header.module) && !is_std_module_name(&header.module) {
        return Err(at(
            start,
            &format!(
                "`{}` is not a module name: use letters, digits and `_`, starting with a letter or `_`",
                header.module
            ),
        ));
    }
    if header.module == "std" {
        return Err(at(
            start,
            "the module name `std` is reserved for the standard library",
        ));
    }
    for (i, used) in header.uses.iter().enumerate() {
        if !is_module_name(used) && !is_std_module_name(used) {
            return Err(at(
                start,
                &format!("`{used}` in `uses` is not a module name"),
            ));
        }
        if *used == header.module || used == DEFAULT_MODULE {
            return Err(at(
                start,
                &format!(
                    "a module cannot use `{used}`: its own and the default module's types need no declaration"
                ),
            ));
        }
        let short = used.rsplit('.').next().unwrap_or(used);
        if header.uses[..i]
            .iter()
            .any(|u| u.rsplit('.').next().unwrap_or(u) == short)
        {
            return Err(at(
                start,
                &format!("two of the used modules are called `{short}`"),
            ));
        }
    }
    let body_start = start + line.len();
    let body = &text[body_start..];
    let actual = body_hash(body);
    if actual != header.hash {
        return Err(at(
            start,
            &format!(
                "the hash {} in the header does not match the contents ({actual}): the file was edited by hand; regenerate it with `Vm::write_interface`",
                header.hash
            ),
        ));
    }
    // The header is blanked out (same length), so offsets in diagnostics stay put.
    let mut masked = String::with_capacity(text.len());
    masked.push_str(&text[..start]);
    masked.push_str(&" ".repeat(content.len()));
    masked.push_str(&text[start + content.len()..]);
    let (ast, diagnostics) = colibri_syntax::parse_interface_file(HOST_FILE, &masked);
    if let Some(d) = diagnostics.iter().find(|d| d.is_error()) {
        return Err(at(d.span.start as usize, &d.message));
    }
    validate(&ast).map_err(|(offset, m)| at(offset as usize, &m))?;
    Ok(HostModule { header, file: ast })
}

/// Whether `name` can be the name of a host module: what an `import` can say.
pub fn is_module_name(name: &str) -> bool {
    let mut chars = name.chars();
    chars.next().is_some_and(|c| c.is_alphabetic() || c == '_')
        && chars.all(|c| c.is_alphanumeric() || c == '_')
}

/// The prefix of a standard library module's name in an interface: `std.math` is the module
/// `import math` and `import std.math` mean (ARCHITECTURE §13).
pub const STD_PREFIX: &str = "std.";

/// Whether `name` is the interface name of a standard library module (`std.math`).
pub fn is_std_module_name(name: &str) -> bool {
    name.strip_prefix(STD_PREFIX).is_some_and(is_module_name)
}

/// How a float constant is written in an interface: the shortest text that reads back to the
/// same value, always with a `.` and without an exponent. `None` for a value that has no such
/// literal (`nan`, infinities, negative, very large or small numbers).
pub fn float_literal(value: f64) -> Option<String> {
    let text = format!("{value:?}");
    (value.is_finite() && value >= 0.0 && text.contains('.') && !text.contains(['e', 'E']))
        .then_some(text)
}

/// Reads `format = 1, module = "host", hash = "..", caps = ["fs"]`.
fn parse_header(args: &str) -> Result<InterfaceHeader, String> {
    let mut format = None;
    let mut module = None;
    let mut hash = None;
    let mut caps = None;
    let mut uses = None;
    let mut rest = args.trim();
    while !rest.is_empty() {
        let (key, after) = rest
            .split_once('=')
            .ok_or("expected `key = value` in the header")?;
        let key = key.trim();
        let after = after.trim_start();
        let (value, tail) = if let Some(inner) = after.strip_prefix('[') {
            let end = inner.find(']').ok_or("an unterminated `[` in the header")?;
            (&after[..end + 2], &inner[end + 1..])
        } else if let Some(inner) = after.strip_prefix('"') {
            let end = inner
                .find('"')
                .ok_or("an unterminated string in the header")?;
            (&after[..end + 2], &inner[end + 1..])
        } else {
            let end = after.find(',').unwrap_or(after.len());
            (&after[..end], &after[end..])
        };
        let value = value.trim();
        let string = |v: &str| {
            v.strip_prefix('"')
                .and_then(|v| v.strip_suffix('"'))
                .map(str::to_string)
                .ok_or_else(|| format!("`{key}` must be a string"))
        };
        match key {
            "format" => {
                format = Some(
                    value
                        .parse::<u32>()
                        .map_err(|_| "`format` must be a number".to_string())?,
                )
            }
            "module" => module = Some(string(value)?),
            "hash" => hash = Some(string(value)?),
            "caps" | "uses" => {
                let inner = value
                    .strip_prefix('[')
                    .and_then(|v| v.strip_suffix(']'))
                    .ok_or_else(|| format!("`{key}` must be a list"))?;
                let mut list = Vec::new();
                for item in inner.split(',').map(str::trim).filter(|s| !s.is_empty()) {
                    list.push(string(item)?);
                }
                if key == "caps" {
                    caps = Some(list);
                } else {
                    uses = Some(list);
                }
            }
            other => return Err(format!("unknown header key `{other}`")),
        }
        rest = tail.trim_start().strip_prefix(',').unwrap_or(tail).trim();
    }
    Ok(InterfaceHeader {
        format: format.ok_or("the header has no `format`")?,
        module: module.ok_or("the header has no `module`")?,
        hash: hash.ok_or("the header has no `hash`")?,
        caps: caps.unwrap_or_default(),
        uses: uses.unwrap_or_default(),
    })
}

/// Checks that a parsed interface holds only what the checker understands, so the checker
/// itself never reports a problem inside it.
fn validate(file: &ast::File) -> Result<(), (u32, String)> {
    for top in &file.items {
        let item = match top {
            TopLevel::Item(item) => item,
            TopLevel::Stmt(stmt) => {
                return Err((
                    stmt.span.start,
                    "an interface file holds declarations only".to_string(),
                ));
            }
        };
        match &item.kind {
            ItemKind::Fn(decl) => {
                check_attrs(item, &["requires", "positional", "typed", "deprecated"])?;
                if decl.body.is_some() {
                    return Err((item.span.start, "an interface function has no body".into()));
                }
                if decl.generics.iter().any(|g| !g.bounds.is_empty()) {
                    return Err((
                        item.span.start,
                        "an interface function's type parameters take no bounds".into(),
                    ));
                }
                if item.attrs.iter().any(|a| a.name.name == "typed") && decl.generics.is_empty() {
                    return Err((
                        item.span.start,
                        "`@typed` marks a generic function: it receives its type arguments".into(),
                    ));
                }
                if decl.receiver.is_some() {
                    return Err((item.span.start, "only methods have a receiver".into()));
                }
            }
            ItemKind::Struct(s) => match s.kind {
                ast::StructKind::Struct => {
                    check_attrs(item, &["deprecated"])?;
                    for field in &s.fields {
                        check_attr_list(&field.attrs, &["deprecated"])?;
                    }
                }
                ast::StructKind::Class => {
                    check_attrs(item, &["host", "deprecated"])?;
                    if !item.attrs.iter().any(|a| a.name.name == "host") {
                        return Err((
                            item.span.start,
                            "a class here must be a `@host class`".into(),
                        ));
                    }
                    if !s.fields.is_empty() || !s.generics.is_empty() {
                        return Err((
                            item.span.start,
                            "a `@host class` has no fields and no type parameters".into(),
                        ));
                    }
                }
            },
            ItemKind::Enum(_) => check_attrs(item, &["module", "deprecated"])?,
            // `type Pos = physics.Pos`: this module's name for a type another module declares
            // (the same Rust type registered by two modules), or `type Pos = Pos` for the
            // default module's.
            ItemKind::TypeAlias(t) => {
                check_attrs(item, &["deprecated"])?;
                let simple = t.generics.is_empty()
                    && matches!(&t.ty.kind, ast::TypeKind::Named { path, args }
                        if args.is_empty() && matches!(path.len(), 1 | 2));
                if !simple {
                    return Err((
                        item.span.start,
                        "a type alias in an interface is `type Name = module.Name` (or `type Name = Name` for a type of the default module)".into(),
                    ));
                }
            }
            ItemKind::Binding(b) => {
                check_attrs(item, &["deprecated"])?;
                let simple = b.kind == ast::BindKind::Const
                    && matches!(b.pat.kind, PatKind::Ident(_))
                    && b.ty.is_some()
                    && match &b.init.kind {
                        ExprKind::Int(_) => true,
                        ExprKind::Float(v) => float_literal(*v).is_some(),
                        _ => false,
                    };
                if !simple {
                    return Err((
                        item.span.start,
                        "a constant in an interface is `const NAME: type = number`".into(),
                    ));
                }
            }
            ItemKind::Impl(decl) => {
                check_attrs(item, &[])?;
                if decl.interface.is_some() || !decl.generics.is_empty() {
                    return Err((
                        item.span.start,
                        "an interface `impl` block holds the methods of a `@host class` only"
                            .into(),
                    ));
                }
                let target = match &decl.target.kind {
                    ast::TypeKind::Named { path, args } if path.len() == 1 && args.is_empty() => {
                        path[0].name.as_str()
                    }
                    _ => "",
                };
                if !is_host_class(file, target) {
                    return Err((
                        decl.target.span.start,
                        "an `impl` block in an interface belongs to a `@host class` declared in the same file".into(),
                    ));
                }
                for member in &decl.items {
                    check_attrs(member, &["requires", "deprecated"])?;
                    let ItemKind::Fn(f) = &member.kind else {
                        return Err((
                            member.span.start,
                            "an interface `impl` block holds methods only".into(),
                        ));
                    };
                    if f.body.is_some() {
                        return Err((member.span.start, "an interface method has no body".into()));
                    }
                    if f.receiver.is_some_and(|r| r.mutable) {
                        return Err((
                            member.span.start,
                            "a method of a host class takes a plain `self`".into(),
                        ));
                    }
                    if f.name.name == "alive" {
                        return Err((
                            f.name.span.start,
                            "`alive` is built into every host class".into(),
                        ));
                    }
                }
            }
            _ => {
                return Err((
                    item.span.start,
                    "an interface file holds functions, constants, structs, enums and host classes only"
                        .to_string(),
                ));
            }
        }
    }
    Ok(())
}

/// Whether `name` is a `@host class` of `file`.
fn is_host_class(file: &ast::File, name: &str) -> bool {
    file.items.iter().any(|top| match top {
        TopLevel::Item(item) => match &item.kind {
            ItemKind::Struct(s) => {
                s.kind == ast::StructKind::Class
                    && s.name.name == name
                    && item.attrs.iter().any(|a| a.name.name == "host")
            }
            _ => false,
        },
        TopLevel::Stmt(_) => false,
    })
}

fn check_attrs(item: &ast::Item, allowed: &[&str]) -> Result<(), (u32, String)> {
    check_attr_list(&item.attrs, allowed)
}

fn check_attr_list(attrs: &[ast::Attr], allowed: &[&str]) -> Result<(), (u32, String)> {
    for attr in attrs {
        let name = attr.name.name.as_str();
        if !allowed.contains(&name) {
            return Err((attr.span.start, format!("unknown attribute `@{name}` here")));
        }
        if name == "requires" {
            let known = match attr.args.as_slice() {
                [arg] => match &arg.kind {
                    ExprKind::Ident(id) => CAPABILITY_NAMES.contains(&id.name.as_str()),
                    _ => false,
                },
                _ => false,
            };
            if !known {
                return Err((
                    attr.span.start,
                    format!(
                        "`@requires` takes one capability: {}",
                        CAPABILITY_NAMES.join(", ")
                    ),
                ));
            }
        } else if name == "deprecated" {
            let plain = match attr.args.as_slice() {
                [] => true,
                [arg] => crate::ffi::plain_string(arg).is_some(),
                _ => false,
            };
            if !plain {
                return Err((
                    attr.span.start,
                    "`@deprecated` takes at most one argument, a plain string".to_string(),
                ));
            }
        } else if !attr.args.is_empty() {
            return Err((attr.span.start, format!("`@{name}` takes no arguments")));
        }
    }
    Ok(())
}

/// The capability a function item requires, if it has `@requires(cap)`.
pub(crate) fn requires_of(item: &ast::Item) -> Option<String> {
    item.attrs.iter().find_map(|a| {
        if a.name.name != "requires" {
            return None;
        }
        match a.args.first().map(|e| &e.kind) {
            Some(ExprKind::Ident(id)) => Some(id.name.clone()),
            _ => None,
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn text(body: &str) -> String {
        format!(
            "// Generated by colibri-runtime; do not edit.\n{}\n{body}",
            header_line("host", &body_hash(body), &[])
        )
    }

    #[test]
    fn fnv_matches_the_reference_vectors() {
        assert_eq!(fnv1a64(b""), 0xcbf2_9ce4_8422_2325);
        assert_eq!(fnv1a64(b"a"), 0xaf63_dc4c_8601_ec8c);
        assert_eq!(fnv1a64(b"foobar"), 0x8594_4171_f739_67e8);
    }

    #[test]
    fn parses_a_well_formed_interface() {
        let env = HostEnv::from_text(&text(
            "struct V { x: f32 }\n@host class W {}\nimpl W {\n    fn step(self, dt: f32)\n}\n@requires(fs) fn read(a: str) -> Result[str]\n",
        ))
        .expect("parses");
        assert_eq!(env.headers().count(), 1);
        assert_eq!(env.default_items().count(), 4);
    }

    #[test]
    fn a_stale_hash_is_reported() {
        let mut t = text("fn f()\n");
        t.push_str("fn g()\n");
        let err = HostEnv::from_text(&t).unwrap_err();
        assert!(err.contains("edited by hand"), "{err}");
    }

    #[test]
    fn bad_headers_and_bodies_are_reported_with_positions() {
        assert!(HostEnv::from_text("fn f()\n").unwrap_err().contains("1:1"));
        let bad_module = format!(
            "{}\nfn f()\n",
            header_line("not a name", &body_hash("fn f()\n"), &[])
        );
        assert!(
            HostEnv::from_text(&bad_module)
                .unwrap_err()
                .contains("not a module name")
        );
        let named = format!(
            "{}\nfn f()\n",
            header_line("physics", &body_hash("fn f()\n"), &[])
        );
        let env = HostEnv::from_text(&named).expect("a named module parses");
        assert_eq!(env.named_modules(), ["physics"]);
        assert_eq!(env.default_items().count(), 0);
        assert_eq!(env.module_items("physics").count(), 1);
        let err = HostEnv::from_text(&text("let x = 1\n")).unwrap_err();
        assert!(err.contains("3:1"), "{err}");
        assert!(HostEnv::from_text(&text("@requires(sudo) fn f()\n")).is_err());
        assert!(HostEnv::from_text(&text("fn f() { }\n")).is_err());
    }

    fn std_text(body: &str) -> String {
        format!(
            "// Generated by colibri-runtime; do not edit.\n{}\n{body}",
            header_line("std.demo", &body_hash(body), &[])
        )
    }

    #[test]
    fn a_standard_library_module_has_the_name_std_dot_something() {
        let env = HostEnv::from_text(&std_text("fn f()\n")).expect("parses");
        assert_eq!(env.named_modules(), ["std.demo"]);
        assert!(is_std_module_name("std.math"));
        assert!(!is_std_module_name("std"));
        assert!(!is_std_module_name("std."));
        assert!(!is_std_module_name("math"));
        assert!(!is_std_module_name("std.a.b"));
        // The bare name stays reserved.
        let bare = format!(
            "{GENERATED}\n{}\nfn f()\n",
            header_line("std", &body_hash("fn f()\n"), &[])
        );
        assert!(HostEnv::from_text(&bare).unwrap_err().contains("reserved"));
    }

    #[test]
    fn constants_generics_and_typed_round_trip_through_the_canonical_text() {
        let body = "const PI: float = 3.141592653589793\nconst N: int = 7\n@typed fn decode[T](text: str) -> Result[T]\nfn pair[A, B](a: A, b: B) -> (B, A)\n";
        let text = std_text(body);
        let env = HostEnv::from_text(&text).expect("parses");
        assert_eq!(env.canonical_texts(), [text]);
    }

    #[test]
    fn what_an_interface_may_not_hold_is_refused_with_a_reason() {
        let bad = |body: &str, wanted: &str| {
            let err = HostEnv::from_text(&std_text(body)).unwrap_err();
            assert!(err.contains(wanted), "{body:?}: {err}");
        };
        bad("let x: int = 1\n", "const NAME: type = number");
        bad("const X: int = 1 + 2\n", "const NAME: type = number");
        bad("const X: str = \"a\"\n", "const NAME: type = number");
        bad("const X = 1\n", "const NAME: type = number");
        bad("const X: float = 1e99\n", "const NAME: type = number");
        bad("@typed fn f()\n", "marks a generic function");
        bad("fn f[T: Eq](a: T)\n", "take no bounds");
        bad("@rename fn f()\n", "unknown attribute");
    }

    #[test]
    fn float_constants_are_plain_decimal_literals() {
        assert_eq!(float_literal(3.5).as_deref(), Some("3.5"));
        assert_eq!(float_literal(0.0).as_deref(), Some("0.0"));
        assert_eq!(float_literal(1.0).as_deref(), Some("1.0"));
        for bad in [f64::NAN, f64::INFINITY, -1.0, 1e300, 1e-10] {
            assert_eq!(float_literal(bad), None, "{bad}");
        }
    }
}
